model Cliente {
  id Int @id
  nome String
  email String? @unique
  saldo Decimal
  tipo String?
  pedidos Pedido[]
}

model Pedido {
  id Int @id
  clienteId Int @map("cliente_id")
  total Decimal?
  cliente Cliente @relation(fields: [clienteId], references: [id])
  items Item[]
}

model Item {
  pedidoId Int @map("pedido_id")
  seq Int
  produto String?
  pedido Pedido @relation(fields: [pedidoId], references: [id])

  @@id([pedidoId, seq])
}

